import sys
def solve(n, m, k, edges):
    import heapq
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))
        adj[v].append((u, w))

    dist = [[float('inf')] * n for _ in range(k + 1)]
    dist[k][0] = 0
    pq = [(0, 0, k)] 

    while pq:
        d, u, rem_k = heapq.heappop(pq)

        if d > dist[rem_k][u]:
            continue

        if u == n - 1:
            return str(d)

        for v, w in adj[u]:
            if d + w < dist[rem_k][v]:
                dist[rem_k][v] = d + w
                heapq.heappush(pq, (d + w, v, rem_k))
            if rem_k > 0 and d < dist[rem_k - 1][v]:
                dist[rem_k - 1][v] = d
                heapq.heappush(pq, (d, v, rem_k - 1))

    ans = min(dist[r][n-1] for r in range(k+1))
    return str(ans) if ans != float('inf') else "-1"


if __name__ == '__main__':
    input_data = sys.stdin.read().split()
    if not input_data: exit()
    n, m, k = int(input_data[0]), int(input_data[1]), int(input_data[2])
    edges = []
    idx = 3
    for _ in range(m):
        edges.append([int(input_data[idx]), int(input_data[idx+1]), int(input_data[idx+2])])
        idx += 3
    print(solve(n, m, k, edges))

